    fun findAnswer(question: String): OfflineAnswer? {
        fun normalize(text: String): String = text.lowercase()
            .replace("ওযু", "অজু").replace("ওজু", "অজু").replace("সালাত", "নামাজ")
            .replace("সাওম", "রোজা").replace("রোজার", "রোজা").replace("নামাজে", "নামাজ").replace("দোয়ার", "দোয়া").replace("যাকাত", "যাকাত")
            .replace(Regex("[؟?.,!ঃ;:()\\[\\]{}\\-—–]"), " ")
            .replace(Regex("\\s+"), " ").trim()
        val q = normalize(question)
        if (q.isBlank()) return null
        val qTokens = q.split(" ").filter { it.length > 1 }.toSet()
        val broadTerms = setOf("নামাজ", "রোজা", "দোয়া", "কুরআন", "হাদিস", "যাকাত", "হজ", "অজু", "ইবাদত", "ইসলাম")
        return answers.map { answer ->
            val score = (answer.keywords + answer.title).fold(0) { total, key ->
                val k = normalize(key)
                val keyTokens = k.split(" ").filter { it.length > 1 }
                total + when {
                    q == k -> 8
                    k in broadTerms -> if (q == k) 4 else 1
                    q.contains(k) && k.length >= 4 -> 5
                    k.contains(q) && q.length >= 4 -> 3
                    else -> keyTokens.count { kt ->
                        kt !in broadTerms && qTokens.any { qt ->
                            qt == kt || (minOf(qt.length, kt.length) >= 3 && (qt.startsWith(kt.take(3)) || kt.startsWith(qt.take(3))))
                        }
                    } * 2
                }
            }
            answer to score
        }.filter { it.second >= 3 }.sortedByDescending { it.second }.firstOrNull()?.first
    }
